  "DETAILED SESSIONS": "\uC0C1\uC138 \uC138\uC158",
  "SURVEY RESPONSES": "\uC124\uBB38 \uC751\uB2F5",
  "MATCHED SESSIONS": "\uC5F0\uACB0\uB41C \uC138\uC158",
  "EASE OF USE": "\uC0AC\uC6A9 \uD3B8\uC758\uC131",
  "Average out of 5": "5\uC810 \uB9CC\uC810 \uD3C9\uADE0",
  "USEFULNESS": "\uC720\uC6A9\uC131",
  "SCORE CLARITY": "\uC810\uC218 \uBA85\uD655\uC131",
  "SELF-RATED FOCUS": "\uC790\uAE30 \uD3C9\uAC00 \uC9D1\uC911\uB3C4",
  "WOULD USE AGAIN": "\uB2E4\uC2DC \uC0AC\uC6A9\uD560 \uC758\uD5A5",
  "LAST 30 DAYS": "\uCD5C\uADFC 30\uC77C",
  "Sessions by day": "\uC77C\uBCC4 \uC138\uC158",
  "PRODUCT SOURCE": "\uC81C\uD488 \uCD9C\uCC98",
  "Study time by source": "\uCD9C\uCC98\uBCC4 \uD559\uC2B5 \uC2DC\uAC04",
  "WHAT PEOPLE SAID": "\uC0AC\uC6A9\uC790 \uC758\uACAC",
  "Recent responses": "\uCD5C\uADFC \uC751\uB2F5",
  "extension": "Chrome \uD655\uC7A5 \uD504\uB85C\uADF8\uB7A8",
  "web": "\uC6F9",
  "No written highlight.": "\uC791\uC131\uB41C \uC7A5\uC810 \uC5C6\uC74C.",
  "No written improvement note.": "\uC791\uC131\uB41C \uAC1C\uC120 \uC758\uACAC \uC5C6\uC74C.",
  "\u{1F4C8} DATA AT A GLANCE": "\u{1F4C8} \uB370\uC774\uD130 \uD55C\uB208\uC5D0 \uBCF4\uAE30",
  "Patterns in the evidence": "\uB370\uC774\uD130\uC758 \uD328\uD134",
  "Daily completed sessions": "\uC77C\uBCC4 \uC644\uB8CC \uC138\uC158",
  "Last 30 days": "\uCD5C\uADFC 30\uC77C",
  "Focus score histogram": "\uC9D1\uC911\uB3C4 \uC810\uC218 \uD788\uC2A4\uD1A0\uADF8\uB7A8",
  "Rating dot plot": "\uD3C9\uAC00 \uC810 \uB3C4\uD45C",
  "Average score out of 5": "5\uC810 \uB9CC\uC810 \uD3C9\uADE0",
  "No data yet": "\uC544\uC9C1 \uB370\uC774\uD130 \uC5C6\uC74C",
